"""All archived studies in a typed 3D index; no inferred mechanism edges."""
import json
from pathlib import Path
from fastapi import APIRouter,HTTPException
router=APIRouter()

def library():
    from deploy.research_library import library as get
    return get()

def bindings(run_id=None):
    lib=library()
    with lib.db() as db:
        rows=db.execute("SELECT sha FROM artifacts WHERE kind='space_binding' ORDER BY created DESC,sha DESC").fetchall()
    result=[];seen=set()
    for row in rows:
        d=lib.artifact(row['sha'])
        key=(d['run_id'],d['model_snapshot'])
        if (run_id is None or d['run_id']==run_id) and key not in seen:result.append({**d,'binding_sha256':row['sha']});seen.add(key)
    return result

def binding(run_id,model_snapshot=None):
    matches=[b for b in bindings(run_id) if model_snapshot is None or b['model_snapshot']==model_snapshot]
    if len(matches)>1:raise ValueError('该运行有多个模型快照，请指定完整model_snapshot。')
    return matches[0] if matches else None

@router.get('/research-space')
def research_space():
    lib=library()
    with lib.db() as db:
        features=db.execute('''SELECT * FROM (SELECT g.*,a.created,ROW_NUMBER() OVER(PARTITION BY g.model,g.id,g.type ORDER BY a.created DESC,g.sha DESC) AS rn
          FROM graph_objects g JOIN artifacts a ON a.sha=g.sha) WHERE rn=1 ORDER BY model,id''').fetchall()
        artifacts=[dict(r) for r in db.execute('SELECT sha,source,model,kind,created,bytes FROM artifacts ORDER BY created DESC,sha DESC')]
    studies=[];all_bindings=bindings()
    for w in lib.workpackages()['workpackages']:
        d=w['body'];bb=[b for b in all_bindings if b['run_id']==d['run_id']];report=d.get('stages',{}).get('registration_validated',{}).get('report_sha256')
        for b in bb or [None]:
          studies.append({'run_id':d['run_id'],'study_key':d['run_id']+'|'+(b['model_snapshot'] if b else ''),'title':d.get('title',d['run_id']),'workpackage_sha256':w['sha'],'report_sha256':b['report_sha256'] if b else report,
              'stages':d['stages'],'model_snapshot':b.get('model_snapshot') if b else None,'binding_sha256':b.get('binding_sha256') if b else None,
              'traces':b.get('traces',[]) if b else [],'localization':'native_binding' if b and b.get('traces') else 'metadata_only'})
    from shared.dist_protocol.mechanism_trace import TraceStore
    models={}
    trace_index=lib.root.parent/'mechanism_traces';traces=[]
    if (trace_index/'index.sqlite3').is_file():
      from server.trace_catalog import dimensions
      traces=dimensions(TraceStore(index=trace_index))
    for t in traces:models[t['model_snapshot']]={**{k:t[k] for k in ['n_layers','d_ff','d_model','n_heads']},'snapshot':t['model_snapshot'],'reference_trace_id':t['trace_id']}
    objects=[{'sha':r['sha'],'id':r['id'],'type':r['type'],'model_snapshot':r['model'],'body':json.loads(r['body'])} for r in features]
    for o in objects:
        if o['model_snapshot'] not in models:models[o['model_snapshot']]={'snapshot':o['model_snapshot'],'localization':'no_native_dimensions'}
    return {'schema':'research_space_index.v1','kind':'real','fingerprint':lib.fingerprint(),'studies':studies,'objects':objects,'artifacts':artifacts,'models':list(models.values()),
        'counts':{'studies':len(studies),'objects':len(objects),'artifacts':len(artifacts)},
        'interpretation':'Native indices locate observations. Unlocated reports remain on an explicitly schematic artifact rack. Layout distance is not model geometry; no evidence promotion.'}

"""Bounded-memory metadata queries; immutable native manifests stay untouched."""
import json

KEYS=['trace_id','run_id','sample_id','entity','scope','split','n_tokens','model_snapshot','deep','readout_positions','n_layers','d_model','d_ff','n_heads','n_kv_heads','head_dim','generation_step']

def refresh(db):
    db.execute('CREATE TABLE IF NOT EXISTS trace_catalog_cache(id TEXT PRIMARY KEY,run TEXT,model TEXT,sample TEXT,parent TEXT,created REAL,summary TEXT)')
    db.execute('CREATE INDEX IF NOT EXISTS trace_catalog_latest ON trace_catalog_cache(run,model,sample,created DESC,id DESC)')
    db.execute('CREATE INDEX IF NOT EXISTS trace_catalog_parent ON trace_catalog_cache(parent)')
    args=','.join("'"+k+"',json_extract(t.body,'$."+k+"')" for k in KEYS)
    db.execute("INSERT OR IGNORE INTO trace_catalog_cache SELECT t.id,json_extract(t.body,'$.run_id'),json_extract(t.body,'$.model_snapshot'),json_extract(t.body,'$.sample_id'),json_extract(t.body,'$.parent_trace_id'),t.created,json_object("+args+") FROM traces t WHERE NOT EXISTS(SELECT 1 FROM trace_catalog_cache c WHERE c.id=t.id)")

def catalog(store,run_id='',parent=''):
    with store.db() as db:
        refresh(db)
        if parent:
            rows=db.execute('SELECT summary FROM trace_catalog_cache WHERE parent=? ORDER BY created,id',(parent,))
        else:
            where='WHERE run=?' if run_id else ''
            rows=db.execute('SELECT summary FROM (SELECT summary,sample,created,id,ROW_NUMBER() OVER(PARTITION BY run,model,sample ORDER BY created DESC,id DESC) rn FROM trace_catalog_cache '+where+') WHERE rn=1 ORDER BY created DESC,id DESC',(run_id,) if run_id else ())
        traces=[]
        for r in rows:
            d=json.loads(r['summary'])
            # sqlite json_object embeds json arrays as arrays, never their string form.
            if isinstance(d['readout_positions'],str):d['readout_positions']=json.loads(d['readout_positions'])
            if parent or ':G' not in d['sample_id']:traces.append(d)
    return {'schema':'mechanism_trace_catalog.v1','traces':traces}

def dimensions(store):
    with store.db() as db:
        refresh(db)
        rows=db.execute('SELECT summary FROM (SELECT summary,ROW_NUMBER() OVER(PARTITION BY model ORDER BY created DESC,id DESC) rn FROM trace_catalog_cache) WHERE rn=1')
        return [json.loads(r['summary']) for r in rows]

"""Read-only native trace queries and bounded CPU parameter contribution checks."""
from functools import lru_cache
from pathlib import Path
import json
import numpy as np
from fastapi import APIRouter,HTTPException,Query
from shared.dist_protocol.mechanism_trace import TraceStore,unbits

router=APIRouter(prefix='/api/traces',tags=['native-mechanism-traces'])
from server.research_space_service import router as research_space_router,binding
router.include_router(research_space_router)
_store=None


def store():
    global _store
    if _store is None:_store=TraceStore()
    return _store


def checked(fn,*args,**kwargs):
    try:return fn(*args,**kwargs)
    except KeyError as e:raise HTTPException(409,str(e)) from e
    except (ValueError,OSError) as e:raise HTTPException(422,str(e)) from e


@router.get('/catalog')
def catalog(run_id:str='',parent:str=''):
    from server.trace_catalog import catalog as query
    if parent:checked(store().manifest,parent)
    return query(store(),run_id,parent)


@router.get('/history')
def history():
    p=Path(__file__).resolve().parents[1]/'research/phase2793/history-index.research.json'
    return json.loads(p.read_text(encoding='utf-8')) if p.is_file() else {'entries':[],'state':'not_migrated'}


@router.get('/context')
def context(run_id:str,model_snapshot:str=''):
    try:linked=binding(run_id,model_snapshot or None)
    except ValueError as e:raise HTTPException(409,str(e)) from e
    if linked:return {**linked.get('context',{}),'run_id':run_id,'model_snapshot':linked['model_snapshot'],'report_sha256':linked['report_sha256'],'graph_sha256':linked['graph_sha256']}
    if run_id=='NMLP-LONG-20261104-v1':
        p=Path(__file__).resolve().parents[1]/'research/native_mlp_long/v1/unified-evidence.research.json'
        if not p.is_file():raise HTTPException(404,'原生MLP长文本证据尚未归档。')
        return json.loads(p.read_text(encoding='utf-8'))
    folder={'P2793-ENTITY-ARBITRATION-v1':'phase2793','P2794-ATOMIC-ARBITRATION-v4':'phase2794'}.get(run_id)
    if folder is None:raise HTTPException(404,'该运行暂无统一研究上下文。')
    p=Path(__file__).resolve().parents[1]/'research'/folder/'unified-evidence.research.json'
    if not p.is_file():raise HTTPException(404,'研究上下文尚未归档。')
    return json.loads(p.read_text(encoding='utf-8'))


@router.get('/profile')
def profile(run_id:str,block:int=Query(0,ge=0,le=35),space:str='mlp'):
    ctx=context(run_id)
    if ctx.get('study_type'):raise HTTPException(404,'该研究不使用文档−现实剖面；请查询对应类型的单元说明书或已归档题族响应。')
    if space not in ['mlp','hidden']:raise HTTPException(422,'只支持原生mlp/hidden空间。')
    folder='phase2793_arbitration' if run_id=='P2793-ENTITY-ARBITRATION-v1' else 'phase2794_arbitration_v4'
    p=Path(__file__).resolve().parents[1]/'tests/glm5/result'/folder/'native-profiles.npz'
    if not p.is_file():raise HTTPException(404,'本节点没有原生响应剖面。')
    with np.load(p) as z:
        if 'profile_block' in z and int(z['profile_block'])!=block:raise HTTPException(404,f'本运行响应剖面仅分析发现集选定的块{int(z["profile_block"])}，其他块的原生阵列仍可查询。')
        disc=z[space+'_discovery_delta'][block];held=z[space+'_heldout_delta'][block]
    return {'schema':'mechanism_response_profile.v1','kind':'real','run_id':run_id,'block':block,'space':space,
        'discovery_delta':disc.tolist(),'heldout_delta':held.tolist(),'n_discovery_entities':ctx.get('n_discovery_entities',16),'n_heldout_entities':ctx.get('n_heldout_entities',32),
        'boundary':'mlp.down_proj.input' if space=='mlp' else f'hidden_states[{block if run_id=="P2793-ENTITY-ARBITRATION-v1" else block+1}]',
        'interpretation':'Document-minus-reality scope-prompt response, including errors; descriptive only, no FWER-controlled semantic or causal claim.'}


@router.get('/{trace_id}/manifest')
def manifest(trace_id:str):return checked(store().manifest,trace_id)[0]


@router.get('/{trace_id}/field')
def field(trace_id:str,block:int=Query(0,ge=0),position:int=Query(...,ge=0),boundary:str='mlp_activation'):
    if boundary in ['hidden_state','embedding']:return checked(hidden_at,trace_id,0 if boundary=='embedding' else block,position)
    return checked(store().field,trace_id,block,position,boundary)


def hidden_at(trace_id,layer,position):
    d,_=store().manifest(trace_id)
    if not d.get('parent_trace_id'):return store().hidden(trace_id,layer,position)
    # Cached generation forwards contain only the newly evaluated token, while
    # manifest positions refer to the complete absolute token history.
    if not 0<=layer<=d['n_layers']:raise ValueError('hidden layer outside trace')
    if position not in d['readout_positions']:raise KeyError('cached forward did not recapture this historical token')
    a=np.load(store().native_path(trace_id,'hidden_readouts.npy'),mmap_mode='r')
    v=unbits(a[layer,d['readout_positions'].index(position)])
    return {'schema':'mechanism_field.v1','trace_id':trace_id,'layer':layer,'position':position,
        'boundary':'embedding' if layer==0 else 'hidden_state','shape':[len(v)],'values':v.tolist(),'source':'native_BF16_bits_cached_current_token'}


@router.get('/{trace_id}/attention-row')
def attention_row(trace_id:str,block:int=Query(0,ge=0),head:int=Query(0,ge=0),query:int=Query(...,ge=0)):
    d,_=checked(store().manifest,trace_id)
    if d.get('parent_trace_id') and query not in d['readout_positions']:raise HTTPException(409,'缓存生成步仅重新采集当前query；历史query请查前缀轨迹。')
    return checked(store().attention_row,trace_id,block,head,query)


def trace_model(d):
    from deploy.parameter_service import catalog
    from deploy.parameter_reader import model_snapshot
    preferred=d.get('provenance',{}).get('model_path','')
    models=sorted(catalog(),key=lambda m:str(m['_path']).replace('\\','/').lower()!=preferred.replace('\\','/').lower())
    for m in models:
        if m['config']['hidden_size']!=d['d_model'] or m['config']['num_hidden_layers']!=d['n_layers']:continue
        if model_snapshot(m['_path'])['sha256']==d['model_snapshot']:return m
    raise ValueError('no configured local weights match the complete trace snapshot')


@lru_cache(maxsize=8)
def tensor_file(folder,name):
    from deploy.parameter_reader import header
    for p in sorted(Path(folder).glob('*.safetensors')):
        h,_,_=header(p)
        if name in h:return str(p)
    raise ValueError('parameter tensor missing')


def parameter(folder,name,index):
    from safetensors import safe_open
    # Reads only selected rows/columns on CPU; no loaded research model/GPU.
    with safe_open(tensor_file(str(folder),name),framework='pt',device='cpu') as f:
        x=f.get_slice(name)[index]
    return x.float().numpy()


def contributions(trace_id,block,position,head,unit,coordinate):
    d,_=store().manifest(trace_id)
    if not 0<=block<d['n_layers'] or not 0<=head<d['n_heads'] or not 0<=unit<d['d_ff'] or not 0<=coordinate<d['d_model']:raise ValueError('index outside native dimensions')
    if position not in d['readout_positions']:raise KeyError('module source decomposition not captured at selected query')
    m=trace_model(d);folder=m['_path'];z=store().block(trace_id,block);r=d['readout_positions'].index(position)
    vals={k:unbits(z[k][r]) for k in ['gate','value','activation','mlp_input','head_z','attention_output','mlp_output','resid_in']}
    prefix=f'model.layers.{block}.';gate=parameter(folder,prefix+'mlp.gate_proj.weight',(unit,slice(None)))
    up=parameter(folder,prefix+'mlp.up_proj.weight',(unit,slice(None)))
    down=parameter(folder,prefix+'mlp.down_proj.weight',(coordinate,slice(None)))
    orow=parameter(folder,prefix+'self_attn.o_proj.weight',(coordinate,slice(None)))
    gt=gate*vals['mlp_input'];ut=up*vals['mlp_input'];dt=down*vals['activation']
    heads=(orow.reshape(d['n_heads'],d['head_dim'])*vals['head_z']).sum(-1)
    # Decompose this unit's gate input with the actual sample RMS held fixed.
    import torch
    mid=(torch.from_numpy(vals['resid_in']).to(torch.bfloat16)+torch.from_numpy(vals['attention_output']).to(torch.bfloat16)).float().numpy()
    gamma=parameter(folder,prefix+'post_attention_layernorm.weight',slice(None))
    read=gate*gamma/np.sqrt(np.mean(mid**2)+m['config']['rms_norm_eps'])
    omatrix=parameter(folder,prefix+'self_attn.o_proj.weight',(slice(None),slice(None)))
    readheads=(omatrix.T@read).reshape(d['n_heads'],d['head_dim'])
    hg=(readheads*vals['head_z']).sum(-1);residual=float(read@vals['resid_in'])
    source=None
    if d['deep']:
        weights=np.asarray(store().attention_row(trace_id,block,head,position)['weights'])
        group=head//(d['n_heads']//d['n_kv_heads']);v=unbits(z['v'][group])
        source=(weights*(v@orow.reshape(d['n_heads'],d['head_dim'])[head])).tolist()
    return {'schema':'mechanism_connections.v1','kind':'real','trace_id':trace_id,'model_snapshot':d['model_snapshot'],
        'local_model_id':m['id'],'verified_full_snapshot':True,'block':block,'position':position,'head':head,'unit':unit,'coordinate':coordinate,
        'gate_terms':gt.tolist(),'value_terms':ut.tolist(),'mlp_output_terms':dt.tolist(),'head_output_terms':heads.tolist(),
        'head_gate_terms':hg.tolist(),'residual_gate_term':residual,'source_token_terms':source,
        'observed':{'gate':float(vals['gate'][unit]),'value':float(vals['value'][unit]),'activation':float(vals['activation'][unit]),
            'mlp_output_coordinate':float(vals['mlp_output'][coordinate]),'attention_output_coordinate':float(vals['attention_output'][coordinate])},
        'reconstructed':{'gate':float(gt.sum(dtype=np.float64)),'value':float(ut.sum(dtype=np.float64)),
            'mlp_output_coordinate':float(dt.sum(dtype=np.float64)),'attention_output_coordinate':float(heads.sum(dtype=np.float64)),
            'gate_via_heads_plus_residual':float(hg.sum(dtype=np.float64)+residual)},
        'source':'exact original parameter slices and native sample responses; FP32 sums vs native BF16 can differ by rounding',
        'edge_types':{'head_to_mlp':'local direct gate-input attribution with actual RMS held fixed; approximate, not causal',
            'mlp_to_output':'sum of all native unit products for selected output coordinate','embedding_to_layers':'residual computational continuity; no direct semantic-causality claim'},
        'causal_evidence':'not established by this arithmetic decomposition'}


@router.get('/{trace_id}/connections')
def connections(trace_id:str,block:int=Query(0,ge=0),position:int=Query(...,ge=0),head:int=Query(0,ge=0),unit:int=Query(0,ge=0),coordinate:int=Query(0,ge=0)):
    return checked(contributions,trace_id,block,position,head,unit,coordinate)

"""Durable, content-addressed research index. Execution != mechanism evidence.

The existing center result store remains authoritative for uploads/audits. This
index retains revisions of local reports and explicit feature/edge declarations;
it never infers a scientific graph from filenames or model-generated prose.
"""
from __future__ import annotations

import hashlib
import json
import os
import sqlite3
import threading
import time
import sys
import tempfile
from contextlib import contextmanager
from pathlib import Path

from fastapi import APIRouter, Header, HTTPException, Query

router = APIRouter(prefix='/api/research-library', tags=['research-library'])
_lock = threading.RLock()


def canonical(doc):
    return json.dumps(doc, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False).encode('utf-8')


def synthetic(doc):
    return str(doc.get('kind','')).lower()=='synthetic' or str(doc.get('mode','')).lower()=='synthetic' or doc.get('synthetic') is True or doc.get('sandbox_synthetic') is True


class Library:
    def __init__(self, root):
        self.root = Path(root)
        self.root.mkdir(parents=True, exist_ok=True)
        with self.db() as db:
            db.executescript('''
                CREATE TABLE IF NOT EXISTS artifacts(sha TEXT PRIMARY KEY,source TEXT NOT NULL,
                    model TEXT NOT NULL,created REAL NOT NULL,kind TEXT NOT NULL,bytes INTEGER NOT NULL);
                CREATE TABLE IF NOT EXISTS observations(sha TEXT NOT NULL,source TEXT NOT NULL,
                    PRIMARY KEY(sha,source));
                CREATE TABLE IF NOT EXISTS graph_objects(sha TEXT NOT NULL,id TEXT NOT NULL,
                    type TEXT NOT NULL,model TEXT NOT NULL,body TEXT NOT NULL,PRIMARY KEY(sha,id,type));
                CREATE INDEX IF NOT EXISTS objects_model ON graph_objects(model,type);
                CREATE TABLE IF NOT EXISTS file_cache(path TEXT PRIMARY KEY,stamp TEXT NOT NULL,sha TEXT NOT NULL);
                CREATE TABLE IF NOT EXISTS metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
                CREATE TABLE IF NOT EXISTS workpackage_revisions(sha TEXT PRIMARY KEY,run_id TEXT NOT NULL);
            ''')

    @contextmanager
    def db(self):
        db = sqlite3.connect(self.root / 'library.sqlite3', timeout=30)
        db.row_factory = sqlite3.Row
        try:
            with db:yield db
        finally:db.close()

    def ingest(self, doc, source, *, kind='report'):
        with _lock:return self._ingest(doc,source,kind=kind)

    def _ingest(self, doc, source, *, kind='report'):
        if not isinstance(doc, dict) or synthetic(doc):
            raise ValueError('Only non-synthetic structured research artifacts can be indexed')
        raw = canonical(doc)
        if len(raw)>16*1024*1024:
            raise ValueError('Research metadata must not exceed 16MB')
        sha = hashlib.sha256(raw).hexdigest()
        if doc.get('schema')=='research_space_binding.v1':
            if doc.get('kind')!='real' or not isinstance(doc.get('run_id'),str) or not doc['run_id'].strip():raise ValueError('real named spatial binding required')
            snapshot=doc.get('model_snapshot','')
            if len(snapshot)!=64 or any(c not in '0123456789abcdef' for c in snapshot):raise ValueError('full binding model snapshot required')
            for key in ['report_sha256','graph_sha256']:
                linked=self.artifact(doc.get(key,''))
                if linked.get('model_snapshot')!=snapshot:raise ValueError('binding proof snapshot differs')
                if key=='graph_sha256' and linked.get('schema')!='research_graph.v1':raise ValueError('binding graph must be an explicit research_graph.v1')
            if not isinstance(doc.get('traces',[]),list) or not isinstance(doc.get('context',{}),dict):raise ValueError('binding trace/context collections required')
            for t in doc.get('traces',[]):
                identity=t.get('trace_id','') if isinstance(t,dict) else ''
                if len(identity)!=64 or any(c not in '0123456789abcdef' for c in identity):raise ValueError('invalid binding trace identity')
                if t.get('manifest_sha256'):
                    manifest=self.artifact(t['manifest_sha256'])
                    if manifest.get('trace_id')!=identity or manifest.get('model_snapshot')!=snapshot:raise ValueError('binding trace manifest differs')
            kind='space_binding'
        identity = doc.get('model_snapshot') or doc.get('model_rev') or doc.get('model') or doc.get('model_id') or ''
        workpackage=doc.get('schema')=='research_workpackage.v1'
        if workpackage and (not isinstance(doc.get('run_id'),str) or not doc['run_id'].strip() or not isinstance(doc.get('stages'),dict)):
            raise ValueError('Workpackage requires run_id and stages')
        model = json.dumps(identity, sort_keys=True, ensure_ascii=False) if isinstance(identity, dict) else str(identity)
        cards = doc.get('feature_cards', [])
        edges = doc.get('graph_edges', [])
        if not isinstance(cards, list) or not isinstance(edges, list) or len(cards)+len(edges)>10000:
            raise ValueError('feature_cards / graph_edges must be bounded lists')
        if cards or edges:
            if doc.get('schema') != 'research_graph.v1' or doc.get('kind') != 'real':
                raise ValueError('Graph declarations require research_graph.v1 and kind=real')
            snapshot = doc.get('model_snapshot')
            if not isinstance(snapshot, str) or len(snapshot)!=64 or any(c not in '0123456789abcdef' for c in snapshot):
                raise ValueError('Graph declarations require an exact model_snapshot sha256')
            ids=set()
            for card in cards:
                if not isinstance(card, dict) or not all(card.get(k) is not None for k in ('id','layer','boundary','index','method','run_id','evidence','counterexamples')):
                    raise ValueError('Feature card lacks identity, boundary, method, run, evidence or counterexamples')
                if not isinstance(card['id'], str) or not card['id'] or card['id'] in ids:
                    raise ValueError('Feature ids must be unique nonempty strings')
                if type(card['layer']) is not int or card['layer']<0 or not isinstance(card['counterexamples'],list):
                    raise ValueError('Feature layer must be a nonnegative integer; counterexamples must be a list')
                if not all(isinstance(card[k],str) and card[k].strip() for k in ('boundary','method','run_id')):
                    raise ValueError('Feature boundary, method and run must be nonempty strings')
                if not isinstance(card['index'],dict) or card['index'].get('space') not in ('residual','mlp','attention','dictionary','parameter'):
                    raise ValueError('Feature index requires an explicit native space')
                ids.add(card['id'])
            card_ids=set(ids)
            for edge in edges:
                if not isinstance(edge,dict) or not all(edge.get(k) for k in ('id','source','target','relation','run_id','evidence')):
                    raise ValueError('Graph edge lacks source, target, relation, run or evidence')
                if edge['target'] not in card_ids or (edge['source'] not in card_ids and not str(edge['source']).startswith('language:')):
                    raise ValueError('Graph endpoints must resolve within this revision or to a typed language node')
                if edge['id'] in ids:
                    raise ValueError('Graph ids must be unique')
                ids.add(edge['id'])
            allowed={'hypothesis','observation','heldout','intervention','parameter_source','negative'}
            for obj in cards+edges:
                if not isinstance(obj['evidence'],dict) or obj['evidence'].get('level') not in allowed or not obj['evidence'].get('artifact_sha256'):
                    raise ValueError('Evidence requires an explicit level and an artifact sha256')
                ref=obj['evidence']['artifact_sha256']
                if not isinstance(ref,str) or len(ref)!=64 or any(c not in '0123456789abcdef' for c in ref):
                    raise ValueError('Invalid evidence artifact sha256')
                with self.db() as db:
                    if not db.execute('SELECT 1 FROM artifacts WHERE sha=?',(ref,)).fetchone():
                        raise ValueError('Evidence artifact must be archived before graph registration')
        dest=self.root/'objects'/sha[:2]/(sha+'.json')
        with self.db() as db:
            if db.execute('SELECT 1 FROM artifacts WHERE sha=?',(sha,)).fetchone():
                if not dest.is_file() or hashlib.sha256(dest.read_bytes()).hexdigest()!=sha:raise ValueError('Archived object missing or corrupted')
                db.execute('INSERT OR IGNORE INTO observations VALUES(?,?)',(sha,str(source)))
                if workpackage:db.execute('INSERT OR IGNORE INTO workpackage_revisions VALUES(?,?)',(sha,doc['run_id']))
                return {'sha256':sha,'features':len(cards),'edges':len(edges)}
        dest.parent.mkdir(parents=True,exist_ok=True)
        # Publish a complete blob atomically without overwriting an existing revision.
        fd,tmp=tempfile.mkstemp(dir=dest.parent,suffix='.tmp')
        try:
            with os.fdopen(fd,'wb') as f:
                f.write(raw);f.flush();os.fsync(f.fileno())
            if dest.exists():
                if dest.read_bytes()!=raw:raise ValueError('Content addressed object mismatch')
            else:
                # Concurrent publishers of this sha have identical canonical bytes.
                try:os.replace(tmp,dest)
                except PermissionError:
                    if not dest.is_file() or dest.read_bytes()!=raw:raise
        finally:
            if os.path.exists(tmp):os.unlink(tmp)
        with self.db() as db:
            db.execute('INSERT OR IGNORE INTO artifacts VALUES(?,?,?,?,?,?)',(sha,str(source),model,time.time(),kind,len(raw)))
            db.execute('INSERT OR IGNORE INTO observations VALUES(?,?)',(sha,str(source)))
            if workpackage:db.execute('INSERT OR IGNORE INTO workpackage_revisions VALUES(?,?)',(sha,doc['run_id']))
            for typ,objects in [('feature',cards),('edge',edges)]:
                for obj in objects:
                    db.execute('INSERT OR IGNORE INTO graph_objects VALUES(?,?,?,?,?)',(sha,obj['id'],typ,model,json.dumps(obj,ensure_ascii=False)))
        return {'sha256':sha,'features':len(cards),'edges':len(edges)}

    def scan(self, root, *, extra_paths=(), source_prefix='', kind='local_report'):
        """New/modified report revisions are archived; missing source files never delete evidence."""
        count=0; errors=[]
        root=Path(root)
        paths=set(root.rglob('report.json')) | set(root.rglob('*.research.json'))
        paths.update(p for p in extra_paths if p.is_file())
        for name in ('neurons','interventions'):
            paths.update((root/name).rglob('*.json'))
        for path in sorted(paths):
            if any('synthetic' in part.lower() for part in path.parts): continue
            st=path.stat()
            if st.st_size>16*1024*1024: continue
            stamp=f'{st.st_mtime_ns}:{st.st_size}'
            with self.db() as db: row=db.execute('SELECT stamp FROM file_cache WHERE path=?',(str(path.resolve()),)).fetchone()
            if row and row['stamp']==stamp:continue
            try:
                raw=path.read_bytes();nonfinite=[]
                def mark(value):
                    nonfinite.append(value)
                    return {'$nonfinite':value}
                doc=json.loads(raw.decode('utf-8-sig'),parse_constant=mark)
                if isinstance(doc,dict) and synthetic(doc):continue
                if nonfinite:
                    if not isinstance(doc,dict) or doc.get('schema')=='research_graph.v1':raise ValueError('Graph declarations require finite JSON values')
                    # Preserve legacy failed/undefined statistics, including exact original UTF-8 bytes.
                    doc={'schema':'legacy_report_import.v1','kind':'legacy_report',
                         'model_snapshot':doc.get('model_snapshot') or doc.get('model_rev') or doc.get('model') or doc.get('model_id'),
                         'source_sha256':hashlib.sha256(raw).hexdigest(),'source_text':raw.decode('utf-8'),
                         'normalization':{'nonfinite_literals':sorted(set(nonfinite)),'note':'$nonfinite marks undefined statistics, never zero or valid evidence'},'report':doc}
                result=self.ingest(doc,source_prefix+str(path.relative_to(root)),kind=kind)
                with self.db() as db:db.execute('INSERT OR REPLACE INTO file_cache VALUES(?,?,?)',(str(path.resolve()),stamp,result['sha256']))
                count+=1
            except (ValueError,OSError,TypeError,AttributeError) as exc:errors.append({'source':str(path.relative_to(root)),'error':str(exc)[:240]})
        return {'new_revisions':count,'errors':errors}

    def summary(self, model=''):
        where=' WHERE model=?' if model else '';args=(model,) if model else ()
        with self.db() as db:
            models=[dict(r) for r in db.execute('SELECT model,COUNT(*) AS artifacts FROM artifacts GROUP BY model')]
            recent=[dict(r) for r in db.execute('SELECT * FROM artifacts'+where+' ORDER BY created DESC LIMIT 100',args)]
            counts={t:db.execute('SELECT COUNT(*) FROM graph_objects WHERE type=?'+(' AND model=?' if model else ''),(t,)+args).fetchone()[0] for t in ('feature','edge')}
            total=db.execute('SELECT COUNT(*) FROM artifacts'+where,args).fetchone()[0]
            status=db.execute("SELECT value FROM metadata WHERE key='sync'").fetchone()
        return {'schema':'research_library.v1','artifacts':total,'graph_revisions':counts,'models':models,'recent':recent,
                'sync':json.loads(status[0]) if status else None,
                'note':'产物归档不表示证据晋级；特征及边必须显式登记并引用已归档证据。'}

    def fingerprint(self):
        with self.db() as db:
            rows=list(db.execute('SELECT sha FROM artifacts ORDER BY sha'))
            if db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='blind_labels'").fetchone():
                rows+=list(db.execute('SELECT sha FROM blind_labels ORDER BY sha'))
        return hashlib.sha256(''.join(r[0] for r in rows).encode()).hexdigest()[:20]

    def graph(self, model='', offset=0, limit=100):
        with self.db() as db:
            rows=db.execute('SELECT * FROM graph_objects'+(' WHERE model=?' if model else '')+' ORDER BY sha,id LIMIT ? OFFSET ?',((model,) if model else ())+(limit,offset)).fetchall()
        return {'objects':[{**dict(r),'body':json.loads(r['body'])} for r in rows],'offset':offset,'limit':limit}

    def artifacts(self,offset=0,limit=50):
        with self.db() as db:
            rows=[dict(r) for r in db.execute('SELECT * FROM artifacts ORDER BY created DESC,sha LIMIT ? OFFSET ?',(limit,offset))]
            total=db.execute('SELECT COUNT(*) FROM artifacts').fetchone()[0]
        return {'artifacts':rows,'offset':offset,'limit':limit,'total':total}

    def fragments(self,offset=0,limit=50):
        """Latest declaration per model + stable feature id, with immutable history.

        Latest is a revision selection, never evidence promotion. Negative revisions
        replace the current view while earlier observations remain accessible.
        """
        with self.db() as db:
            base='''SELECT g.*,a.created,ROW_NUMBER() OVER
                (PARTITION BY g.model,g.id ORDER BY a.created DESC,g.sha DESC) AS revision_rank
                FROM graph_objects g JOIN artifacts a ON a.sha=g.sha WHERE g.type='feature' '''
            total=db.execute('SELECT COUNT(*) FROM ('+base+') WHERE revision_rank=1').fetchone()[0]
            rows=db.execute('SELECT * FROM ('+base+') WHERE revision_rank=1 ORDER BY created DESC,id LIMIT ? OFFSET ?',(limit,offset)).fetchall()
            features=[]
            for r in rows:
                history=[{'sha':h['sha'],'level':json.loads(h['body'])['evidence']['level'],'created':h['created']}
                    for h in db.execute('''SELECT g.sha,g.body,a.created FROM graph_objects g JOIN artifacts a ON a.sha=g.sha
                        WHERE g.type='feature' AND g.model=? AND g.id=? ORDER BY a.created DESC,g.sha DESC''',(r['model'],r['id']))]
                features.append({'sha':r['sha'],'id':r['id'],'model_snapshot':r['model'],'body':json.loads(r['body']),'history':history})
        return {'schema':'research_fragments.v1','features':features,'total':total,'offset':offset,'limit':limit}

    def workpackages(self):
        with self.db() as db:
            rows=db.execute('''SELECT * FROM (SELECT w.*,a.created,ROW_NUMBER() OVER
                (PARTITION BY w.run_id ORDER BY a.created DESC,w.sha DESC) AS revision_rank
                FROM workpackage_revisions w JOIN artifacts a ON a.sha=w.sha)
                WHERE revision_rank=1 ORDER BY created DESC''').fetchall()
        return {'schema':'research_workpackages.v1','workpackages':[{'sha':r['sha'],'body':self.artifact(r['sha'])} for r in rows]}

    def artifact(self, sha):
        if len(sha)!=64 or any(c not in '0123456789abcdef' for c in sha):raise ValueError('Invalid sha256')
        raw=(self.root/'objects'/sha[:2]/(sha+'.json')).read_bytes()
        if hashlib.sha256(raw).hexdigest()!=sha:raise ValueError('Artifact checksum mismatch')
        return json.loads(raw)


def services():
    if 'distributed_service' in sys.modules:
        return sys.modules['distributed_service']
    from . import distributed_service as D
    return D


def library():
    D=services()
